// widgets/src/editor.ts
async function createEditor(container) {
  const socket = new classic.Socket("socket");
  const editor = new NodeEditor();
  const area = new AreaPlugin(container);
  const connection = new ConnectionPlugin();
  const render = new LitPlugin();
  index.selectableNodes(area, index.selector(), {
    accumulating: index.accumulateOnCtrl()
  });
  render.addPreset(index3.classic.setup());
  connection.addPreset(index2.classic.setup());
  editor.use(area);
  area.use(connection);
  area.use(render);
  index.simpleNodesOrder(area);
  const a5 = new classic.Node("A");
  a5.addControl("a", new classic.InputControl("text", { initial: "a" }));
  a5.addOutput("a", new classic.Output(socket));
  await editor.addNode(a5);
  const b4 = new classic.Node("B");
  b4.addControl("b", new classic.InputControl("text", { initial: "b" }));
  b4.addInput("b", new classic.Input(socket));
  await editor.addNode(b4);
  await editor.addConnection(new classic.Connection(a5, "a", b4, "b"));
  await area.translate(a5.id, { x: 0, y: 0 });
  await area.translate(b4.id, { x: 270, y: 0 });
  setTimeout(() => {
    index.zoomAt(area, editor.getNodes());
  }, 10);
  return {
    destroy: () => area.destroy()
  };
}

